    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.7rem;
    color: #72767d;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    color: #dcddde;
}

/* Reactions */
.message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 4px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dcddde;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #4f545c;
}

/* Thread link */
.thread-link {
    background: none;
    border: none;
    color: #00aff4;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 4px;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Hover actions */
.message-actions {
    position: absolute;
    top: -8px;
    right: 12px;
    display: flex;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}

.action-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    cursor: pointer;
    padding: 4px 8px;
    font-size: 0.75rem;
    border-radius: 3px;
}

.action-btn:hover {
    background: #4f545c;
    color: #fff;
}

/* Emoji picker */
.emoji-picker {
    position: absolute;
    top: -44px;
    right: 12px;
    display: flex;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 6px;
    padding: 6px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}

.emoji-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.2rem;
    padding: 2px 4px;
    border-radius: 4px;
}

.emoji-btn:hover {
    background: #4f545c;
}

/* Message Input */
.message-input-area {
    padding: 12px 20px;
    display: flex;
    gap: 8px;
    border-top: 1px solid #202225;
    background: #36393f;
}

.message-textarea {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 8px;
    padding: 10px 14px;
    color: #dcddde;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

.message-textarea::placeholder {
    color: #72767d;
}

.send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
.thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2f3136;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #202225;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
}

.thread-header h4 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
}

.close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    cursor: pointer;
    font-size: 1.2rem;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #4f545c;
    color: #fff;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
    border-left: 3px solid #5865f2;
    margin: 12px;
    border-radius: 4px;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 16px;
}

.thread-reply {
    padding: 8px 0;
    border-bottom: 1px solid #3f4248;
}

.thread-reply:last-child {
    border-bottom: none;
}
