    background: none;
    border: none;
    color: #b9bbbe;
    cursor: pointer;
    padding: 4px 8px;
    font-size: 0.75rem;
    border-radius: 3px;
}

.action-btn:hover {
    background: #4f545c;
    color: #fff;
