    font-size: 1rem;
}

.close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    cursor: pointer;
    font-size: 1.2rem;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #4f545c;
    color: #fff;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
    border-left: 3px solid #5865f2;
    margin: 12px;
    border-radius: 4px;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 16px;
}

.thread-reply {
    padding: 8px 0;
    border-bottom: 1px solid #3f4248;
}

.thread-reply:last-child {
    border-bottom: none;
}

